            need(res["key"].startswith("Fine, 40% and up,Getting low, 20 to 39%,Low, under 20%"), f"the ranges legend isn't right: {res['key']}")
            need("on battery" in res["tip"] and "%" in res["tip"], f"hover doesn't say time and battery: {res['tip']}")
