import calendar, json, os, random, re, subprocess, sys, time
ROOT = sys.argv[1]
sys.path.insert(0, ROOT + "/routine"); sys.path.insert(0, ROOT + "/app")
import tick, mailguard as M, routines, incidents, direct_line
def need(ok, why):
    if not ok:
        print("FAIL " + why); sys.exit(1)
