open(os.path.join(os.environ["HQ_JOB_RUN"], "mail.log"), "w").write("--- 2026-11-03 10:00:00\nAdded 1 mail.\n--- exit 0\n")
json.dump({"pid": None, "started": time.time() - 200}, open(tick.MAIL_STATE, "w"))
