            for cmd in (f"{ul} weekly fixed 90 {said}", f"{ul} 5-hour fixed 95 {said}", f"{ul} fable fixed 95 {said}", f"{ul} weekly moving {said}"):
                d = pol.decide("Bash", {"command": cmd})
