        need(hook("mcp__g__create_event", {"summary": "Lunch", "startTime": "2026-11-07T12:00:00", "endTime": "2026-11-07T13:00:00", "attendees": [{"email": "a@b.c"}]}).returncode == 2, "an add with a guest")
