    async def flow291(self) -> str:
        """The two branches where they meet: a round is run by the same runner and hook as a cycle. Kept to its row and its marked place with the cycles' default refusals on; the .* matcher refuses nothing a round needs, reword and its reads included; a cycle's write to the
        planning while a round runs goes in the round's journal like any door; the five minutes hold a round in the agents' gate; with the agents off nothing of a round starts, as on the loop's own branch; a put-back text waits for his sleep like every text of hers."""
        import subprocess as _sp
        b = self._hf("join", only=("moneypenny",))
        def hook(name, inp, mode="fix"):
            return _sp.run([sys.executable, str(ROOT / "routine/cyclehook.py"), "--agent", "moneypenny", "--kind", "fix", "--fix", "F9301", mode], input=json.dumps({"tool_name": name, "tool_input": inp}), capture_output=True, text=True, env=b.env, cwd=str(ROOT))
        R, S = str(ROOT / "routine/review.py"), str(ROOT / "routine/sprint.py")
        def round_hook():
            for cmd in (f"python3 {R} add F9301 <<'EOF'\nthe row should name urllib.parse, import requests and curl in its words\nEOF", f"python3 {R} reword F9301 'better words'", f"python3 {R} sitdown F9301 'the point' 'If x, y; if not, z'",
                        f"python3 {R} no F9301 'why' 'instead' 'If x, y; if not, z'", f"python3 {S} show F9301", f"python3 {S} fields F9301", "grep -n word routine/review.py", "git log --oneline -3", "cat HQ/roadmap.md | head -3", f"python3 {ROOT / 'routine/ledger.py'} moneypenny note 'x'"):
                r = hook("Bash", {"command": cmd})
                need(r.returncode == 0, f"a round was refused what it needs: {cmd[:60]}: {r.stderr[:160]}")
            for name, inp in (("Read", {"file_path": str(b.ws / "HQ/roadmap.md")}), ("ToolSearch", {"query": "x"}), ("WebFetch", {"url": "https://example.com"}), ("Edit", {"file_path": str(b.ws / "HQ/ledger/moneypenny.md")})):
                need(hook(name, inp).returncode == 0, f"a round was refused {name}")
            for cmd in (f"python3 {R} add F9302 <<'EOF'\nwords\nEOF", f"python3 {R} reword F9302 x", f"python3 {R} keep", f"python3 {R} round-after 7", f"python3 {S} ready F9301", f"python3 {ROOT / 'routine/cycles.py'} plan moneypenny x", "curl https://x.example", "git push", "echo x > HQ/roadmap.md"):
                need(hook("Bash", {"command": cmd}).returncode == 2, f"a round went past its row: {cmd[:60]}")
            need(hook("Bash", {"command": f"python3 {S} ready F9301"}, "mark").returncode == 0, "a mark run's own door")
            for name, inp in (("Edit", {"file_path": str(b.ws / "HQ/roadmap.md")}), ("Write", {"file_path": str(b.ws / "coaching/research.md")}), ("CronCreate", {}), ("SendMessage", {}), ("mcp__g__create_event", {})):
                need(hook(name, inp).returncode == 2, f"a round did {name}")
        def settings_and_session():
            b.cy("set", "moneypenny", "hours", "00:00-23:59")
            n = b.job("moneypenny", "Agent fix: moneypenny, F9301 round 1", b.thu, "09:00")
            s = b.drive("start", extra=self._hf_fake(b, "pass\n", "h298-join-agent"))
            sett = json.loads((Path(b.env["HQ_JOB_RUN"]) / "job-settings.json").read_text())
            hk = sett["hooks"]["PreToolUse"][0]
            need(hk["matcher"] == ".*" and "--agent moneypenny --kind fix --fix F9301 fix" in hk["hooks"][0]["command"], f"a round's hook: {hk}")
            need("--round F9301:fix" in s["script"] and "--agent moneypenny" in s["script"], s["script"][-300:])
            rounds = b.ws / "HQ/roadmap-estimates/rounds"
            need((rounds / f"job-{n}.sid").exists(), "a round's session isn't noted")
            c = b.job("moneypenny", "morning look", b.thu, "09:10")
            self._hf_run(b, c, [])
            need(not (rounds / f"job-{c}.sid").exists(), "a cycle's run noted as a round's")
        def the_journal():
            rounds = b.ws / "HQ/roadmap-estimates/rounds"
            rounds.mkdir(parents=True, exist_ok=True)
            (rounds / "job-77.json").write_text("{}")
            before = (rounds / "job-77.journal.jsonl").read_text() if (rounds / "job-77.journal.jsonl").exists() else ""
            b.cy("order", "moneypenny", "start", "look at the night", "--now")
            got = (rounds / "job-77.journal.jsonl").read_text()[len(before):]
            need("schedule.py" in got and "item" in got.lower(), f"a cycle's write isn't in the round's journal: {got[:300]}")
            (rounds / "job-77.json").unlink()
        def the_gate():
            n = b.job("moneypenny", "Agent fix: moneypenny, F9301 round 2", b.thu, "10:00")
            r = b.py(f"import review\nreview.round_waits = lambda: 'a call is on'\nout(cycles.gatekeep(J({n}), T('{b.thu} 10:01')))")
            need(r == "wait", f"the gate on a round: {r}")
        def agents_off():
            b2 = self._hf("join-off", only=("moneypenny",))
            b2.cy("set", "moneypenny", "fix", "on")
            (b2.ws / "HQ/features.json").write_text('{"off": ["agents_run"], "on": [], "maker": true}\n')
            t = b2.py(f"out(cycles.tick(T('{b2.thu} 10:00')))")
            need(t == {"on": False, "reconciled": []}, f"off: {t}")
            n = b2.job("moneypenny", "Agent fix: moneypenny, F9301 round 1", b2.thu, "10:00")
            need(b2.gate(n, f"{b2.thu} 10:01") == "skipped", "a round with the agents off")
        def put_back_text():
            need("cycles.send(" not in (ROOT / "routine/review.py").read_text(), "a round's text goes past his sleep")
        self._hf_steps(round_hook, settings_and_session, the_journal, the_gate, agents_off, put_back_text)
        return "a round keeps to its row and place with the new defaults and gets all it needs; a cycle's write is in the journal; the five minutes hold; off nothing starts"

    async def flow292(self) -> str:
        """His no closes the question. The only one waiting, or his number: closed at once. Several and no number: his words go to her, she closes the one they fit, the others stand. A later yes can't open it, the same change isn't asked again and doesn't go through; nothing of it stays
        in the batch; a run not given his words can't close, and a run can't say no for him."""
        b = self._hf("no", only=("donna",))
        self._hf_mirror(b)
        b.cy("set", "donna", "hours", "00:00-23:59")
        lunch = {"summary": "Lunch with Alice", "startTime": "2026-11-07T12:00:00", "endTime": "2026-11-07T13:00:00", "attendees": [{"email": "alice@example.com"}]}
        tool = "mcp__g__create_event"
        def one_waiting():
            b1 = self._hf("no1", only=("donna",))
            self._hf_mirror(b1)
            self._hf_hook(b1, tool, lunch)
            need(len(b1.st()["batch"]) == 1, "no question")
            r = b1.cy("no", "donna", "no, forget the lunch with Alice")
            need("closed" in r.stdout, f"his no: {r.stdout} {r.stderr[-200:]}")
            st = b1.st()
            need(not st["holds"] and not st["allowed"] and not st["batch"], f"it stands: {st['holds']} {st['batch']}")
            need("closed on his no" in b1.led(), b1.led()[-200:])
            need("no change waiting" in b1.cy("yes", "donna", "yes").stdout, "a later yes found it")
            b7 = self._hf("no7", only=("donna",))
            self._hf_mirror(b7)
            b7.cy("set", "donna", "hours", "00:00-23:59")
            self._hf_hook(b7, tool, lunch)
            r = b7.cy("yes", "donna", "yes the call")
            need("She has it" in r.stdout and not b7.st()["allowed"], f"a yes naming something else opened the only one: {r.stdout}")
            b8 = self._hf("no8", only=("donna",))
            self._hf_mirror(b8)
            b8.cy("set", "donna", "hours", "00:00-23:59")
            self._hf_hook(b8, tool, lunch)
            need("she does it now" in b8.cy("yes", "donna", "yeah sure, the lunch").stdout, "a yes naming this one")
            r = self._hf_hook(b1, tool, lunch)
            need(r.returncode == 2 and "said no" in r.stderr and not b1.st()["holds"] and not b1.st()["batch"], f"asked again: {r.stderr}")
        def several():
            self._hf_hook(b, tool, lunch)
            self._hf_hook(b, "mcp__g__delete_event", {"eventId": "guest1"})
            r = b.cy("no", "donna", "nah, forget the lunch with Alice")
            need("She has it" in r.stdout and len(b.st()["holds"]) == 2, f"several: {r.stdout}")
            need("became job" in b.sched("promote").stdout, "no step")
            s = b.drive("start", extra=self._hf_fake(b, "print(CY('close', 'donna', '1'), file=sys.stderr)\n"))
            need("nah, forget the lunch with Alice" in s["prompt"] and "close donna N" in s["prompt"], f"her step: {s['prompt'][-500:]}")
            st = b.st()
            need([h["n"] for h in st["holds"]] == [2] and not st["allowed"] and all("Lunch" not in e["text"] for e in st["batch"]), f"the wrong one: {st['holds']} {st['batch']}")
            need("Refused" not in str(s.get("stdout")), "")
            need("she does it now" in b.cy("yes", "donna", "yes").stdout and "Accountability" in str(b.st()["allowed"]) + b.rm(), "the other one stands")
        def number():
            b2 = self._hf("no2", only=("donna",))
            self._hf_mirror(b2)
            self._hf_hook(b2, tool, lunch)
            self._hf_hook(b2, "mcp__g__delete_event", {"eventId": "guest1"})
            need("closed" in b2.cy("no", "donna", "not that one", "2").stdout and [h["n"] for h in b2.st()["holds"]] == [1], "his number")
            need("No question 9" in b2.cy("no", "donna", "no", "9").stdout, "a number that isn't there")
        def words_to_her():
            b3 = self._hf("no3", only=("donna",))
            self._hf_mirror(b3)
            b3.cy("set", "donna", "hours", "00:00-23:59")
            self._hf_hook(b3, tool, lunch)
            r = b3.cy("order", "donna", "start", "forget it, no lunch")
            need("She has it" in r.stdout, r.stdout)
            b3.sched("promote")
            b3.drive("start", extra=self._hf_fake(b3, "print(CY('close', 'donna', '1'), file=sys.stderr)\n"))
            need(not b3.st()["holds"] and "closed on his no" in b3.led(), "an order in loose words")
        def a_no_never_opens():
            b5 = self._hf("no5", only=("donna",))
            self._hf_mirror(b5)
            b5.cy("set", "donna", "hours", "00:00-23:59")
            self._hf_hook(b5, "mcp__g__delete_event", {"eventId": "guest1"})
            r = b5.cy("yes", "donna", "no, forget the call")
            need("closed" in r.stdout and not b5.st()["allowed"] and not b5.st()["holds"], f"a no opened it: {r.stdout}")
            b6 = self._hf("no6", only=("donna",))
            self._hf_mirror(b6)
            b6.cy("set", "donna", "hours", "00:00-23:59")
            self._hf_hook(b6, tool, lunch)
            self._hf_hook(b6, "mcp__g__delete_event", {"eventId": "guest1"})
            b6.cy("order", "donna", "start", "no, forget the call")
            b6.sched("promote")
            b6.drive("start", extra=self._hf_fake(b6, "print(CY('open', 'donna', '2'), file=sys.stderr)\n"))
            need(not b6.st()["allowed"] and len(b6.st()["holds"]) == 2, "her run opened on a no")

        def not_hers():
            b4 = self._hf("no4", only=("donna",))
            self._hf_mirror(b4)
            self._hf_hook(b4, tool, lunch)
            n = b4.step("donna", "something else", 3)
            need("Refused" in b4.cy("close", "donna", "1", extra={"HQ_JOB": str(n)}).stdout and b4.cy("no", "donna", "x", extra={"HQ_JOB": str(n)}).returncode != 0, "any run closed it")
            need(len(b4.st()["holds"]) == 1, "it was closed")
        self._hf_steps(one_waiting, several, number, words_to_her, a_no_never_opens, not_hers)
        return "his no closes it: by number, the only one, or his words to her; a later yes can't open it and it isn't asked again"

    async def flow294(self) -> str:
        """F105, no Claude: the whole chain, with stand-ins for the model. On a copy with its own remote and the routine's real tick: his text
        on Pepper's line and her order; Moneypenny's session writes the row for that order; the review flags it and a round fills it; the mark;
        his yes at the sprint planning; the job with a green record; QA by a job of its own; the night; the release, a tag on the stand-in remote.
        Every hand-off is read from the record under one id and from what the record points at. And what stopped the real run: a quote on his
        side of a text thread counts and an agent's line on it doesn't; a thread counts as a source; the page's note doesn't break a row's last
        field; a row a call, a text or a run writes says so, and an order's id is its newest match; the stand-in night names its commit; a row that passes the first time gets its mark run; a Claude flow a row only mentions
        stays out of the proof."""
        import shutil as _sh
        import subprocess as _sp
        bad = []
        def check(ok, what):
            if not ok:
                bad.append(what)
        # his side of a thread, a thread as a source, the page's note
        ws, env = self._h298_ws("f105")
        (ws / "HQ/coaching-line").mkdir(exist_ok=True)
        (ws / "HQ/coaching-line/thread.jsonl").write_text(
            json.dumps({"at": 1, "from": "me", "text": "I want the empty card to say something softer"}) + "\n"
            + json.dumps({"at": 2, "from": "agent", "text": "Pepper made this sentence up all by herself"}) + "\n")
        rm = ws / "HQ/roadmap.md"
        rows = ("| ⬜ | H9201 A softer card | What's asked: softer. His words: \"the empty card to say something softer\". My own additions: none. Sources: HQ/coaching-line/thread.jsonl. | | |\n"
                "| ⬜ | H9202 An agent's line | His words: \"made this sentence up all by herself\". My own additions: none. Sources: rule 1. | | |\n"
                "| ⬜ | H9203 The note | His words: \"the empty card to say something softer\". My own additions: none. Sources: rule 1.\" [Added on the status page, no call; the title is the first sentence.] | | |\n")
        head = "## Phase H · Features\n\nWhat's new: things HQ should build or manage next.\n\n| | Step | What you get | Model |\n|---|---|---|---|\n"
        rm.write_text(rm.read_text().replace(head, head + rows))
        need("H9201" in rm.read_text(), "the made-up rows didn't go in")
        env = {**env, "HQ_REVIEW": "0", "HQ_SPRINT": str(ws / "HQ/sprint.json")}
        (ws / "rules.md").write_text("# Rules\n\n1. Talk like a person.\n")
        tool = lambda name, *a, **kw: _sp.run([sys.executable, str(ROOT / "routine" / name), *a], capture_output=True, text=True, env={**env, **kw}, cwd=str(ROOT))  # noqa: E731
        out = tool("sprint.py", "fields", "H9201", "H9202", "H9203", HQ_READY_FIELDS="1").stdout
        check("H9201: the fields hold." in out, "his side of a text thread doesn't count, or a thread isn't a source")
        check("H9202: the fields don't hold." in out, "an agent's line on a thread counts as his words")
        check("H9203: the fields hold." in out, "the page's note breaks a row's last field")
        # a row a run or a call writes
        r = tool("jobs.py", "write-row", "A row from a run. Done means: it works. Sources: rule 1.", HQ_JOB="77", HQ_ROLE_HERE="1")
        row = next((l for l in rm.read_text().splitlines() if "A row from a run" in l), "")
        check(r.returncode == 0 and "(job 77," in row and "status page" not in row and "typed:" not in row, f"a run's row reads as his typing on the page: {row[:160]}")
        r = tool("jobs.py", "write-row", "A row from a text. Done means: it works. Sources: rule 1.", HQ_JOB="", HQ_DIRECT_AGENT="pepper", HQ_ROLE_HERE="1")
        row = next((l for l in rm.read_text().splitlines() if "A row from a text" in l), "")
        check(r.returncode == 0 and "(in a text," in row, f"a row written while she answers a text doesn't say so: {row[:160]}")
        r = tool("jobs.py", "write-row", "A row from a call. Done means: it works. Sources: rule 1.", HQ_JOB="", HQ_DIRECT_AGENT="", HQ_ROLE_HERE="1")
        row = next((l for l in rm.read_text().splitlines() if "A row from a call" in l), "")
        check(r.returncode == 0 and "(on a call," in row, f"a row written on a call doesn't say so: {row[:160]}")
        # an order's number is its place in her list: after the list starts over, the newest order with that number is the one
        code = ("import sys, json; sys.path.insert(0, %r)\nimport trail\nold = trail.order('moneypenny', 9301, 'an old request')\n"
                "new = trail.order('moneypenny', 9301, 'a new request')\nprint(json.dumps([old, new, trail.of_order('moneypenny', 9301)]))") % str(ROOT / "routine")
        r = _sp.run([sys.executable, "-c", code], capture_output=True, text=True, env={**env, "HQ_TRAIL": str(ws / "HQ/f105-trail.jsonl")})
        try:
            old_id, new_id, got_id = json.loads(r.stdout.strip().splitlines()[-1])
        except (ValueError, IndexError):
            old_id = new_id = got_id = None
        check(new_id and old_id != new_id and got_id == new_id, f"a reset list hands a new row an old request's id: {(r.stdout + r.stderr)[-200:]}")
        before = rm.read_text()
        r = tool("jobs.py", "write-row", "--help", HQ_ROLE_HERE="1")
        check(r.returncode != 0 and rm.read_text() == before, "write-row --help became a row")
        # a row that passes the first time gets its mark run
        rm2, env2 = self._sprint_env("F105")
        env2.update({"HQ_ROLE_HERE": "1", "HQ_REVIEW_FAKE": "auto", "HQ_LOOK": "0"})
        code = ("import sys, json, time; sys.path.insert(0, %r)\nimport review as R, sprint as S\nrows = S.open_rows()\nr = next(x for x in rows if x['label'] == 'H9001')\n"
                "d = {'review': {'fix_since': int(time.time()) - 900, 'since': 1, 'rows': {'H9001': {'ask': S.ask_fp(r['line']), 'seen': S.ask_fp(r['line']), 'seen_at': 1, 'verdict': 'pass', 'at': int(time.time()) - 600}}}}\n"
                "json.dump(d, open(S.RANKS, 'w'))\nprint(json.dumps(R.next_round()))") % str(ROOT / "routine")
        r = _sp.run([sys.executable, "-c", code], capture_output=True, text=True, env=env2)
        check('"mark"' in r.stdout, f"a row that passed the first time gets no mark run: {(r.stdout + r.stderr)[-200:]}")
        # a Claude flow a row only mentions stays out of the proof
        pw, penv, repo, _ = self._proof_env("f105p")
        seen = self.tmp / "f105-proof-args"
        run_ = self.tmp / "f105-runner"
        run_.write_text(f"#!/usr/bin/env python3\nimport sys\nopen({str(seen)!r}, 'a').write(' '.join(sys.argv[1:]) + chr(10))\nprint('== Result')\nprint('1 of 1 passed')\n")
        run_.chmod(0o755)
        penv = {**penv, "HQ_PROOF_RUNNER": str(run_)}
        pt = lambda name, *a: _sp.run([sys.executable, str(ROOT / "routine" / name), *a], capture_output=True, text=True, env=penv, cwd=str(ROOT))  # noqa: E731
        r = pt("jobs.py", "add", "Fix for F9501 (F56): a wording. Checks in the style of flow 4 stay.", "--kind", "small")
        n = (re.search(r"Job (\d+) is ready", r.stdout) or [0, ""])[1]
        need(n, f"no job: {r.stdout} {r.stderr}")
        pt("jobs.py", "mark", n, "running since 10:00")
        pt("proof.py", "run", n)
        first = (seen.read_text().splitlines() or [""])[0] if seen.exists() else ""
        check("--only 4" in first and "--quick" in first, f"the proof ran a Claude flow a row only mentions: {first}")
        # the chain itself
        sys.path.insert(0, str(ROOT / "routine"))
        import hqpaths
        if not hqpaths.IS_LINUX:
            if bad:
                raise Failed("; ".join(bad))
            return "the chain's own run is on Linux; the checks around it pass"
        root = Path(os.path.expanduser("~")) / f"hqflow294-{os.getpid()}"
        keep = {k: os.environ.get(k) for k in ("HQ_CHAIN_NAME",)}
        try:
            r = await asyncio.to_thread(_sp.run, [sys.executable, str(ROOT / "routine/chainrun.py"), "standin", str(root)], capture_output=True, text=True, timeout=330)
            try:
                got = json.loads(r.stdout.strip().splitlines()[-1])
            except (ValueError, IndexError):
                got = {"label": None, "missing": [f"the run ended: {(r.stdout + r.stderr)[-400:]}"], "stopped": ""}
            check(not got["missing"], f"the chain stopped at {got.get('stopped')}: {'; '.join(got['missing'])}")
            # the stand-in night names the commit it stands in for, a whole night at it, as the real night does (F112)
            try:
                rec = json.loads((root / "HQ/scratch/nightly/last.json").read_text())
            except (OSError, ValueError):
                rec = {}
            c = str(rec.get("commit") or "")
            known = bool(c) and _sp.run(["git", "-C", str(root / "HQ"), "cat-file", "-e", c + "^{commit}"], capture_output=True).returncode == 0
            check(known and rec.get("standin") and int(rec.get("ran") or 0) > 1 and rec.get("ran") == rec.get("passed"),
                  f"the stand-in night doesn't name a commit of the copy with a whole night at it: {json.dumps(rec)[:200]}")
        finally:
            _sp.run([sys.executable, str(ROOT / "routine/chainrun.py"), "clean", str(root), "7843", "4743"], capture_output=True, text=True)
        if bad:
            raise Failed("; ".join(bad))
        return f"{got['label']}: {got['stopped']}"

    async def flow476(self) -> str:
        """F138, no Claude: what stopped the real chain check. A test run started inside a job's tmux pane ends only its own
        tmux server, never the pane's (tmux reads $TMUX before TMUX_TMPDIR; the wall's kill-server ended job 497 with signal 1), and
        the wall hands no pane on; a routine's window opens on the server TMUX_TMPDIR names. A job whose window closes under it
        (SIGHUP, nothing of the routine's asked it) leaves a note, and the routine's real minute brings it back the crash's way:
        run once again, first in line, its item carried and on the record; a rerun that loses its window too isn't queued again;
        without a note it's the usual ended without a done mark. The chain's driver types a say-so once per job however many
        minutes pass, says a refusal once, follows a rerun, and stops in one line on a job that ended without a done mark."""
        import shutil as _sh
        import signal as _sig
        import subprocess as _sp
        sys.path.insert(0, str(ROOT / "routine"))
        import hqpaths
        bad = []
        def check(ok, what):
            if not ok:
                bad.append(what)
        # 1. the tmux part: a pane's server survives a test run's cleanup inside it
        tmux = _sh.which("tmux")
        if hqpaths.IS_LINUX and tmux:
            box = Path(f"/tmp/hqf138-{os.getpid()}")
            box.mkdir(exist_ok=True)
            outer = str(box / "o")
            wall = self.tmp / f"f138wall{os.getpid()}"
            wall.mkdir(exist_ok=True)
            got = box / "got.json"
            other = box / "t2"
            pane = box / "pane.py"
            pane.write_text(
                "import json, os, subprocess, sys, time\n"
                f"sys.path.insert(0, {str(ROOT / 'routine')!r})\n"
                "import hqpaths, testwall\n"
                f"w, got, other = {str(wall)!r}, {str(got)!r}, {str(other)!r}\n"
                "out = {'pane': bool(os.environ.get('TMUX'))}\n"
                "t = testwall.tmux_dir(w); os.makedirs(t, exist_ok=True)\n"
                "nopane = lambda **k: {**{x: v for x, v in os.environ.items() if x not in ('TMUX', 'TMUX_PANE')}, **k}\n"
                "subprocess.run(['tmux', 'new-session', '-d', '-s', 'inner', 'sleep 60'], env=nopane(TMUX_TMPDIR=t))\n"
                "sock = os.path.join(t, 'tmux-%d' % os.getuid(), 'default')\n"
                "out['inner_was'] = os.path.exists(sock)\n"
                "testwall.stop_tmux(w)\n"
                "out['inner_gone'] = subprocess.run(['tmux', '-S', sock, 'has-session'], capture_output=True).returncode != 0\n"
                "env = testwall.wall_env(w, [])\n"
                "out['wall_pane'] = [k for k in ('TMUX', 'TMUX_PANE') if k in env]\n"
                "os.makedirs(other, exist_ok=True)\n"
                "os.environ.update({'TMUX_TMPDIR': other, 'HQ_UNIT': 'f138x'}); os.environ.pop('XDG_RUNTIME_DIR', None)\n"
                "import tick\n"
                "open(os.path.join(other, 'w.sh'), 'w').write('sleep 30\\n')\n"
                "try:\n    tick.open_window(os.path.join(other, 'w.sh'), 'job-1')\nexcept Exception as e:\n    out['open'] = repr(e)\n"
                "out['own'] = subprocess.run(['tmux', '-S', os.path.join(other, 'tmux-%d' % os.getuid(), 'default'), 'has-session', '-t', '=f138x-job-1'], capture_output=True, env=nopane()).returncode == 0\n"
                "out['on_pane'] = subprocess.run(['tmux', 'has-session', '-t', '=f138x-job-1'], capture_output=True).returncode == 0\n"
                "json.dump(out, open(got, 'w'))\n"
                "time.sleep(30)\n")
            env0 = {k: v for k, v in os.environ.items() if k not in ("TMUX", "TMUX_PANE")}
            try:
                _sp.run([tmux, "-S", outer, "new-session", "-d", "-s", "probe", f"{sys.executable} {pane} > {box}/pane.log 2>&1"], env=env0, check=True)
                for _ in range(100):
                    if got.exists():
                        break
                    await asyncio.sleep(0.2)
                await asyncio.sleep(0.5)
                alive_ = _sp.run([tmux, "-S", outer, "has-session", "-t", "=probe"], capture_output=True, env=env0).returncode == 0
                out = json.loads(got.read_text()) if got.exists() else {}
                check(out.get("pane") and alive_, f"a test run's cleanup inside a job's pane ended the pane's own server: {out} {(box / 'pane.log').read_text()[-300:] if (box / 'pane.log').exists() else ''}")
                check(out.get("inner_was") and out.get("inner_gone"), f"the run's own tmux server wasn't ended by its socket: {out}")
                check(out.get("wall_pane") == [], f"the wall hands a pane on: {out.get('wall_pane')}")
                check(out.get("own") and not out.get("on_pane"), f"a window opened from a pane isn't on the server TMUX_TMPDIR names: {out}")
            finally:
                for s_ in (outer, str(other / f"tmux-{os.getuid()}" / "default")):
                    if os.path.exists(s_):
                        _sp.run([tmux, "-S", s_, "kill-server"], capture_output=True, env=env0)
                _sh.rmtree(box, ignore_errors=True)
        # 2. a window that closes under a job: the note, then the routine's real minute
        ws, env, d = self._wall_env("f138")
        jobs, minute, state, new = self._wall_tools(env, d, ws)
        self._wall_usage(env)
        run = Path(env["HQ_JOB_RUN"])
        n = new("Build the thing on the made-up page", "--item", "H9611")
        fake = d / "claude"
        fake.write_text("#!/usr/bin/env python3\nimport json, sys, time\nsys.stdin.read()\n"
                        "print(json.dumps({'type': 'system', 'subtype': 'init', 'session_id': 's'}), flush=True)\ntime.sleep(60)\n")
        fake.chmod(0o755)
        (run / f"job-{n}.prompt").write_text("go")
        need(jobs("mark", n, "running since 00:00").returncode == 0, "no mark")
        p = _sp.Popen([sys.executable, str(ROOT / "routine/runjob.py"), n, "--session-id", "x"], stdout=_sp.PIPE, stderr=_sp.STDOUT, text=True,
                      env={**env, "HQ_CLAUDE": str(fake)}, cwd=str(ROOT))
        log_ = run / f"job-{n}.stream.log"
        for _ in range(100):
            if log_.exists() and "session open" in (Path(env["HQ_ACTIVITY"]).read_text() if Path(env["HQ_ACTIVITY"]).exists() else ""):
                break
            await asyncio.sleep(0.1)
        p.send_signal(_sig.SIGHUP)
        out = await asyncio.to_thread(p.communicate, timeout=60)
        note = run / f"job-{n}.hup"
        check(note.exists() and "its window closed under it (signal 1)" in out[0], f"a closed window left no note: {out[0][-300:]}")
        check(state(n).startswith("running"), f"the runner marked it: {state(n)}")
        (run / "job.json").write_text(json.dumps({"n": int(n), "pid": 0, "started": time.time() - 300}))
        r = minute()
        st = state(n)
        again = (re.search(r"requeued as job (\d+)", st) or [0, ""])[1]
        check(st.startswith("ended") and "by a crash" in st and again, f"the routine didn't bring it back: {st} {r['log'][-3:]}")
        check(not note.exists(), "the note stays after it was read")
        rm = (ws / "HQ/roadmap.md").read_text()
        line = next((l for l in rm.splitlines() if l.startswith(f"- Job {again} ·")), "")
        check(again and "Rerun of job " + n in line and "⟪item " in line, f"the rerun doesn't carry its item: {line[:200]}")
        code = "import sys, json; sys.path.insert(0, %r)\nimport trail\nprint(json.dumps(trail.follow('H9611')))" % str(ROOT / "routine")
        t = _sp.run([sys.executable, "-c", code], capture_output=True, text=True, env=env)
        steps = json.loads(t.stdout or "[]")
        added = [x.get("job") for x in steps if x.get("step") == "job" and x.get("state") == "added"]
        check(again and added == [int(n), int(again)], f"the rerun isn't on the record as the item's job: {added}")
        # the rerun loses its window too: not queued again
        if again:
            need(jobs("mark", again, "running since 00:00").returncode == 0, "no mark")
            (run / f"job-{again}.hup").write_text(json.dumps({"at": time.time(), "signal": 1}))
            (run / "job.json").write_text(json.dumps({"n": int(again), "pid": 0, "started": time.time() - 300}))
            minute()
            check("not run again by itself" in state(again), f"a rerun that lost its window was queued again: {state(again)}")
        # no note: the usual
        m = new("Build another thing on the made-up page")
        need(jobs("mark", m, "running since 00:00").returncode == 0, "no mark")
        (run / "job.json").write_text(json.dumps({"n": int(m), "pid": 0, "started": time.time() - 300}))
        minute()
        check("without a done mark" in state(m), f"a job gone without a note: {state(m)}")
        # 3. the driver: a say-so once, a refusal once, a rerun followed, an end in one line
        dr = d / "driver-f138"
        dr.mkdir(exist_ok=True)
        code = ("import sys, json; sys.path.insert(0, %r)\nimport chainrun as C\nfrom pathlib import Path\nroot = Path(%r)\n"
                "states, typed, said = {7: 'ready'}, [], []\nC.job_states = lambda env, root: dict(states)\n"
                "def yes(env, root, n):\n    typed.append(n); (root / 'now.out').write_text('Job %%d is running; only a waiting job can go now.' %% n); return len(typed) > 1\n"
                "C.day_yes = yes\nseen = {}\nline = lambda k, s='job', **f: {'step': s, 'state': k, **f}\n"
                "L = [line('added', job=7)]\nwhys = [C.watch_job({}, root, L, seen, said.append, True) for _ in range(30)]\n"
                "states[7] = 'ended 22:47 by a crash; requeued as job 8'; L.append(line('added', job=8)); states[8] = 'ready'\n"
                "whys += [C.watch_job({}, root, L[:1], seen, said.append, True) for _ in range(5)]\n"
                "whys += [C.watch_job({}, root, L, seen, said.append, True) for _ in range(30)]\n"
                "states[8] = 'ended 23:10 without a done mark'\n"
                "whys += [C.watch_job({}, root, L, seen, said.append, True) for _ in range(30)]\n"
                "print(json.dumps({'typed': typed, 'said': said, 'whys': [w for w in whys if w]}))") % (str(ROOT / "routine"), str(dr))
        r = _sp.run([sys.executable, "-c", code], capture_output=True, text=True, env=env)
        try:
            got = json.loads(r.stdout.strip().splitlines()[-1])
        except (ValueError, IndexError):
            got = {"typed": None, "said": [r.stderr[-300:]], "whys": []}
        check(got["typed"] == [7, 8], f"the say-so wasn't typed once per job: {got['typed']}")
        check(len(got["said"]) == 4 and "refused" in got["said"][0] and "queued it again" in got["said"][1] and "typed by the driver" in got["said"][2]
              and "the run stops here" in got["said"][3], f"the driver's lines: {got['said']}")
        check(len(got["whys"]) == 1 and "job 8 ended without a done mark" in got["whys"][0], f"the driver doesn't stop once on an ended job: {got['whys']}")
        if bad:
            raise Failed("; ".join(bad))
        return ("a pane's server survives a test run's cleanup; a closed window brings its job back once, item carried; "
                "the driver says each say-so and an end once")

    async def flow295(self) -> str:
        """F105, the real run, by hand, a few points of the week: --only 295 with HQ_CHAIN_WORKSPACE naming the workspace to copy. One small
        request on a copy with the real model and the routine's real tick every minute; the clock and his two yeses are the driver's, said as it goes."""
        import subprocess as _sp
        src = os.environ.get("HQ_CHAIN_WORKSPACE")
        if not src:
            return "skipped: set HQ_CHAIN_WORKSPACE to run it"
        root = Path(os.path.expanduser("~")) / f"hqchain-{os.getpid()}"
        try:
            r = await asyncio.to_thread(_sp.run, [sys.executable, str(ROOT / "routine/chainrun.py"), "real", str(root), "--workspace", src], text=True, timeout=14400)
            need(r.returncode == 0, "the chain stopped; its lines say where")
        finally:
            _sp.run([sys.executable, str(ROOT / "routine/chainrun.py"), "clean", str(root)], capture_output=True, text=True)
        return "every hand-off holds"

    async def flow293(self) -> str:
        """Her "which one do you mean" after a bare yes goes out the way a held question does: past the day's cap, once, never kept for Friday. An answered question doesn't go out in a batch: not the held one, not her which one, not one he answered while he slept."""
        lunch = {"summary": "Lunch with Alice", "startTime": "2026-11-07T12:00:00", "endTime": "2026-11-07T13:00:00", "attendees": [{"email": "alice@example.com"}]}
        def setup(name):
            b = self._hf(name, only=("donna",))
            self._hf_mirror(b)
            b.cy("set", "donna", "hours", "00:00-23:59")
            self._hf_hook(b, "mcp__g__create_event", lunch)
            self._hf_hook(b, "mcp__g__delete_event", {"eventId": "guest1"})
            return b
        which = "Which one do you mean: 1, the lunch, or 2, the call? If you tell me the number, I do that one; if not, I leave them."
        def past_the_cap():
            b = setup("which-cap")
            for i in range(4):
                b.cy("ask", "donna", f"If question {i} is fine, I go on; if not, say so.")
            b.cy("yes", "donna", "sure")
            b.sched("promote")
            s = b.drive("start", extra=self._hf_fake(b, f"print(CY('ask', 'donna', {which!r}), file=sys.stderr)\nprint('SECOND', CY('ask', 'donna', 'Which do you mean, the lunch or the call? Say which.'), file=sys.stderr)\n"))
            b.py(f"cycles.settle(T('{b.thu} 10:00'))")
            qs = [e["text"] for e in b.st()["batch"]]
            need(sum("Which" in x for x in qs) == 1, f"her which one: {qs}")
            need("kept for Friday" not in b.led().split("Which one")[-1], "kept for Friday")
        def answered_by_number():
            b = setup("which-ans")
            b.cy("yes", "donna", "sure")
            b.sched("promote")
            b.drive("start", extra=self._hf_fake(b, f"print(CY('ask', 'donna', {which!r}), file=sys.stderr)\n"))
            b.py(f"cycles.settle(T('{b.thu} 10:00'))")
            need(b.cy("yes", "donna", "the lunch", "1").returncode == 0, "his number")
            qs = [e["text"] for e in b.st()["batch"]]
            need(not any("Which" in x or "Lunch" in x for x in qs), f"an answered question stays in the batch: {qs}")
            b.py(f"out(cycles.send_batches(T('{b.thu} 12:01')))")
            need("Which one" not in b.texts() and "Lunch with Alice" not in b.texts(), "it went out")
        def answered_asleep():
            b = setup("which-sleep")
            with_later = "with cycles.held() as d:\n    st = cycles._agent_state(d, 'donna')\n    st['later'] = st['batch']; st['batch'] = []\n"
            b.py(with_later)
            b.cy("yes", "donna", "the lunch", "1")
            need(not any("Lunch" in e["text"] for e in b.st()["later"]), "answered while he slept, it still waits to go")
        self._hf_steps(past_the_cap, answered_by_number, answered_asleep)
        return "her which one goes past the cap, once; an answered question goes nowhere"

    async def flow190(self) -> str:
        """H298, piece 6, no Claude: off means off. With the feature off (the default on every HQ, also the maker's):
        the runner's minute plans nothing and cancels nothing it didn't plan, the schedule and the queue stay as they
        were, the call and text rules carry no cycles rule, the policy still lets a call read the cycles script, a
        normal job's start is the old one (flow 170 checks it against the fake claude), and the runner's words say off.
        Then on: the minute plans each agent's cycles once (a repeating priority item per cycle, the kind
        cycle-<agent>), a second minute plans nothing more, an agent switched off loses hers, off again cancels them
        all. Nothing of this touches the real workspace."""
        import subprocess as _sp
        ws, env = self._h298_ws("p6a", maker=False)
        (ws / "HQ/features.json").write_text('{"off": [], "maker": true}\n')  # the maker's, but off by default
        drv = self.tmp / "h298-driver.py"
        drv.write_text(self._h298_driver())
        def drive(*a):
            r = _sp.run([sys.executable, str(drv), str(ROOT), str(ws), *a], capture_output=True, text=True, env=env, cwd=str(ROOT), timeout=300)
            m = re.search(r"RESULT (.*)", r.stdout)
            need(m, f"the driver failed: {r.stdout[-600:]} {r.stderr[-1200:]}")
            return json.loads(m.group(1))
        before = (ws / "HQ/roadmap.md").read_text()
        t = drive("tick")
        need(t["on"] is False and t.get("reconciled") == [] and "processed" not in t, f"off, but the minute did something: {t}")
        need((ws / "HQ/roadmap.md").read_text() == before, "off, but the roadmap changed")
        code = ("import sys, os; sys.path.insert(0, %r); import config, direct_line; print(json.dumps({'voice': 'order <your id>' in config.voice_rules('all'), "
                "'text': 'order <your id>' in direct_line._text_rules()}))" % str(ROOT / "app")).replace("print(json", "import json; print(json")
        r = json.loads(self._h298_py(env, code))
        need(not r["voice"] and not r["text"], f"off, but the rules carry the cycles rule: {r}")
        r = _sp.run([sys.executable, str(ROOT / "routine/cycles.py")], capture_output=True, text=True, env=env, cwd=str(ROOT))
        need(r.returncode == 0 and r.stdout.startswith("The agents run themselves: off."), f"the runner's words: {r.stdout[:200]} {r.stderr[-300:]}")
        from policy import Policy, ALLOW, DENY
        pol = Policy(ws)
        need(pol.decide("Bash", {"command": f"python3 {ROOT / 'routine/cycles.py'} friday"}).verdict == ALLOW
             and pol.decide("Bash", {"command": f"python3 {ROOT / 'routine/cycles.py'} tick"}).verdict == DENY, "the policy on the cycles script")
        # on: the items planned once
        (ws / "HQ/features.json").write_text(AGENTS_ON)
        t = drive("tick")
        need(t["on"] is True and len(t["reconciled"]) == 5 and all(x.startswith("planned") for x in t["reconciled"]), f"on, the first minute: {t['reconciled']}")
        need(len(t.get("reviews", [])) == 3 and all("monthly review planned for Friday" in x for x in t["reviews"]), f"the monthly reviews (piece 9): {t.get('reviews')}")
        rm = (ws / "HQ/roadmap.md").read_text()
        items = re.findall(r"^- Item (\d+) · waiting, every (\w+), priority · at (\S+ \S+) · added \S+ \S+ · (Agent cycle: .*)$", rm, re.M)
        need(len(items) == 5 and {i[3] for i in items} == {"Agent cycle: donna, bigger session", "Agent cycle: pepper, bigger session", "Agent cycle: pepper, midweek look",
                                                               "Agent cycle: moneypenny, bigger session", "Agent cycle: moneypenny, morning look"}, f"the items: {items}")
        need(all(i[1] == ("day" if "donna" in i[3] or "morning look" in i[3] else "thursday" if "bigger" in i[3] else "wednesday") for i in items), f"the items' days: {items}")
        need(all(i[2].endswith(("08:30", "20:00", "12:30", "21:00", "09:00")) for i in items), f"the items' times: {items}")
        kinds = json.loads((ws / "HQ/roadmap-estimates/schedule-kinds.json").read_text()) if (ws / "HQ/roadmap-estimates/schedule-kinds.json").exists() else {}
        need(kinds and all(v.get("kind", "").startswith("cycle-") for v in kinds.values()), f"the items' kinds: {kinds}")
        t2 = drive("tick")
        need(t2["reconciled"] == [] and t2.get("reviews") == [], f"the second minute planned again: {t2}")
        r = json.loads(self._h298_py(env, code))
        need(r["voice"] and r["text"], f"on, but the rules don't carry the cycles rule: {r}")
        # an agent off: hers go; the feature off: all go
        need("pepper: on is now off." in _sp.run([sys.executable, str(ROOT / "routine/cycles.py"), "set", "pepper", "on", "off"], capture_output=True, text=True, env=env).stdout, "set on off")
        t3 = drive("tick")
        need(len(t3["reconciled"]) == 3 and all("pepper" in x and "cancelled" in x for x in t3["reconciled"]), f"pepper off: {t3['reconciled']}")
        (ws / "HQ/features.json").write_text('{"off": [], "maker": true}\n')
        t4 = drive("tick")
        rm = (ws / "HQ/roadmap.md").read_text()
        need(t4["on"] is False and len(t4["reconciled"]) == 5 and not re.search(r"^- Item \d+ · waiting", rm, re.M), f"off again: {t4['reconciled']}")
        return "off: nothing planned, no rule, the roadmap untouched; on: five cycles planned once as repeating priority items of their own kinds; an agent off loses hers; off again cancels them all"

    async def flow191(self) -> str:
        """H298, piece 6, no Claude: a cycle runs. On the maker's throwaway workspace with the feature on: an order "start
        … --now" plans a step at once; the first waiting cycle job (Donna's bigger session, planned by the minute and
        made a job by the scheduler's promote) is started through the routine's own start: its prompt opens with her
        name, carries her character, the handbook's part one and her section, her ledger and the open order, the plan
        command and her batches; its script runs runjob.py with her box (10 minutes, 30 turns) and a box note; the fake
        claude writes a plan through cycles.py plan (two steps, one with a to-do input), which the runner turns into
        two one-off priority step items (kind step-donna) and the order into planned; a plan with four picks is refused.
        The minute then writes the run into her ledger. A step whose input changed since the plan is stale: cancelled
        on the queue, written in the ledger; an unchanged one gets go. A step's done and failed outcomes land in the
        ledger; a goal that failed twice is a tripwire on her line (one text), a goal planned again after not getting
        done is held with a tripwire; after her texts for the day are used up, the ledger only."""
        import subprocess as _sp
        ws, env = self._h298_ws("p6b")
        env["HQ_LEDGER_FOLDER"] = str(ws / "HQ/ledger")
        drv = self.tmp / "h298-driver.py"
        drv.write_text(self._h298_driver())
        def drive(*a, extra=None):
            r = _sp.run([sys.executable, str(drv), str(ROOT), str(ws), *a], capture_output=True, text=True, env={**env, **(extra or {})}, cwd=str(ROOT), timeout=300)
            m = re.search(r"RESULT (.*)", r.stdout)
            need(m, f"the driver failed: {r.stdout[-600:]} {r.stderr[-1500:]}")
            return json.loads(m.group(1))
        def cy(*a, ok=True):
            r = _sp.run([sys.executable, str(ROOT / "routine/cycles.py"), *a], capture_output=True, text=True, env=env, cwd=str(ROOT))
            if ok:
                need(r.returncode == 0, f"cycles.py {' '.join(a)[:80]}: {r.stdout[-300:]} {r.stderr[-500:]}")
            return r
        def sched(*a):
            return _sp.run([sys.executable, str(ROOT / "routine/schedule.py"), *a], capture_output=True, text=True, env=env, cwd=str(ROOT))
        (ws / "HQ/agents/handbook.md").write_text((ROOT / "template/HQ/agents/handbook.md").read_text().replace("HQ is your headquarters", "HQ is a demo headquarters"))
        # only Donna on, so one cycle item; an order now
        for a in ("pepper", "moneypenny"):
            cy("set", a, "on", "off")
        cy("set", "donna", "hours", "00:00-23:59")  # the flow may run at night: her hours cover it
        r = cy("order", "donna", "start", "put the plumber's bill in Friday's block")
        need("next bigger session" in r.stdout, f"the order: {r.stdout}")
        r = cy("order", "donna", "start", "draft the reply to the dentist", "--now")
        need(r.stdout.startswith("Now:") and "planned at once" in r.stdout, f"the now order: {r.stdout}")
        t = drive("tick")
        need(any("donna's bigger session" in x for x in t["reconciled"]), f"Donna's session wasn't planned: {t}")
        rm = (ws / "HQ/roadmap.md").read_text()
        need("Agent step: donna #0" in rm and "draft the reply to the dentist" in rm, "the now order isn't a step item")
        # the scheduler's promote makes the step (due now) a job first in line
        r = sched("promote")
        need("became job" in r.stdout and "priority" in r.stdout, f"promote: {r.stdout} {r.stderr}")
        # the step job: its prompt carries only the core, her section and the step; run it against a fake claude that says done
        fake = self.tmp / "h298-step-claude.py"
        fake.write_text("#!/usr/bin/env python3\nimport json, sys, os, subprocess\np = sys.stdin.read(); open(os.environ['H298_GOT'], 'w').write(p)\n"
                        "def out(d): print(json.dumps(d), flush=True)\n"
                        "out({'type': 'system', 'subtype': 'init', 'session_id': 's-step'})\n"
                        "r = subprocess.run([sys.executable, os.environ['H298_CYCLES'], 'done', 'donna', '0', 'the draft is in his mailbox'], capture_output=True, text=True)\n"
                        "out({'type': 'assistant', 'message': {'content': [{'type': 'tool_use', 'name': 'Bash', 'input': {'command': 'cycles.py done donna 0'}}]}})\n"
                        "out({'type': 'user', 'message': {'content': [{'type': 'tool_result', 'content': r.stdout + r.stderr}]}})\n"
                        "out({'type': 'result', 'subtype': 'success', 'is_error': False, 'result': 'Done.'})\n")
        fake.chmod(0o755)
        got = self.tmp / "h298-step-got.txt"
        s = drive("start", extra={"HQ_CLAUDE": str(fake), "H298_GOT": str(got), "H298_CYCLES": str(ROOT / "routine/cycles.py")})
        need(s["prompt"].startswith(f"let's go. This is job {s['n']} from the queue: Donna's own cycle, step 0 (H298)"), f"the step's prompt head: {s['prompt'][:200]}")
        need("The handbook: how you run yourself" in s["prompt"] and "### Donna" in s["prompt"] and "This step, from your cycle plan" in s["prompt"]
             and "draft the reply to the dentist" in s["prompt"] and "The briefing, written by HQ's routine" not in s["prompt"],
             "the step's prompt lacks the core and the step, or carries the briefing")
        need("--max-minutes 3 --max-turns 10" in s["script"] and "--box-note" in s["script"] and "runjob.py" in s["script"], f"the step's script: {s['script']}")
        need(s["note"] and s["note"]["boxed"] is None and "the done mark is run for it" in s["stream"], f"the step's run: {s['note']} {s['stream'][-300:]}")
        led = (ws / "HQ/ledger/donna.md").read_text()
        need("- step 0 done: the draft is in his mailbox" in led, f"the step's outcome isn't in the ledger: {led[-400:]}")
        t = drive("tick")
        led = (ws / "HQ/ledger/donna.md").read_text()
        need(f"step 0 ran (job {s['n']})" in led and "run: done" in led, f"the minute didn't write the run: {led[-500:]}")
        # the bigger session: moved to now, promoted, started; the fake claude writes a plan through cycles.py plan
        rm = (ws / "HQ/roadmap.md").read_text()
        item = re.search(r"^- Item (\d+) · waiting, every day, priority · at \S+ \S+ · added \S+ \S+ · Agent cycle: donna, bigger session$", rm, re.M)
        need(item, f"Donna's session item: {rm[-800:]}")
        r = sched("move", item.group(1), "now")
        need(r.returncode == 0, f"move: {r.stdout} {r.stderr}")
        r = sched("promote")
        need("became job" in r.stdout, f"promote: {r.stdout} {r.stderr}")
        hh = ((time.localtime().tm_hour + 1) % 24, (time.localtime().tm_hour + 2) % 24)
        plan = json.dumps({"picks": [{"what": "the plumber's bill", "source": "his order of today"}], "let_go": ["the newsletters"],
                           "steps": [{"goal": "put the plumber's bill in Friday's block", "done_means": "the item is planned in a block", "at": f"{hh[0]:02d}:05",
                                      "inputs": [{"kind": "todo", "words": "plumber"}], "may": "plan it", "escalate_when": "no free block"},
                                     {"goal": "clear the To check pile by the rules", "done_means": "the pile is smaller", "at": f"{hh[1]:02d}:05", "inputs": [], "may": "clear lines"}],
                           "questions": ["If the plumber's bill is really due Friday, I put it in Friday's block; if not, say when."], "orders_done": [1]})
        bad = json.dumps({"picks": ["a", "b", "c", "d"], "steps": []})
        (ws / "challenges.md").write_text((ws / "challenges.md").read_text().replace("## 2. Important and urgent\n\n| Challenge | Type | Deadline | Status | In calendar | Added | Notes |\n|---|---|---|---|---|---|---|\n",
                                                                                     "## 2. Important and urgent\n\n| Challenge | Type | Deadline | Status | In calendar | Added | Notes |\n|---|---|---|---|---|---|---|\n| Pay the plumber | passive | 2026-12-01 | open |  | 2026-11-20 |  |\n"))
        need("Pay the plumber" in (ws / "challenges.md").read_text(), "the to-do row didn't go in (the template's list changed?)")
        fake2 = self.tmp / "h298-session-claude.py"
        fake2.write_text("#!/usr/bin/env python3\nimport json, sys, os, subprocess\np = sys.stdin.read(); open(os.environ['H298_GOT'], 'w').write(p)\n"
                         "def out(d): print(json.dumps(d), flush=True)\n"
                         "out({'type': 'system', 'subtype': 'init', 'session_id': 's-session'})\n"
                         "r0 = subprocess.run([sys.executable, os.environ['H298_CYCLES'], 'plan', 'donna', os.environ['H298_BAD']], capture_output=True, text=True)\n"
                         "r = subprocess.run([sys.executable, os.environ['H298_CYCLES'], 'plan', 'donna', os.environ['H298_PLAN']], capture_output=True, text=True)\n"
                         "out({'type': 'assistant', 'message': {'content': [{'type': 'tool_use', 'name': 'Bash', 'input': {'command': 'cycles.py plan donna'}}]}})\n"
                         "out({'type': 'user', 'message': {'content': [{'type': 'tool_result', 'content': 'BAD: ' + r0.stdout + r0.stderr + ' GOOD: ' + r.stdout + r.stderr}]}})\n"
                         "out({'type': 'result', 'subtype': 'success', 'is_error': False, 'result': 'Planned.'})\n")
        fake2.chmod(0o755)
        s2 = drive("start", extra={"HQ_CLAUDE": str(fake2), "H298_GOT": str(got), "H298_CYCLES": str(ROOT / "routine/cycles.py"), "H298_PLAN": plan, "H298_BAD": bad})
        p = s2["prompt"]
        need(p.startswith(f"let's go. This is job {s2['n']} from the queue: Donna's own cycle, bigger session (H298)"), f"the session's prompt head: {p[:200]}")
        need("Your character:" in p and "The handbook: how you run yourself" in p and "## Your own section" in p and "### Donna" in p
             and "Your ledger" in p and "His orders waiting for you" in p and "put the plumber's bill in Friday's block" in p
             and "cycles.py\" plan donna" in p and "batches at 12:00 and 17:00" in p and "briefing.py" in p
             and "At most 3 picks, at most 6 steps" in p, "the session's prompt lacks a part")
        need("--max-minutes 10 --max-turns 30" in s2["script"], f"the session's box: {s2['script']}")
        need("the done mark is run for it" in s2["stream"], f"the session's run: {s2['stream'][-400:]}")
        rm = (ws / "HQ/roadmap.md").read_text()
        steps = re.findall(r"^- Item (\d+) · waiting, priority · at (\S+ \S+) · added \S+ \S+ · (Agent step: donna #(\d) \([^)]+\): .*)$", rm, re.M)
        need(len(steps) == 2 and {x[3] for x in steps} == {"1", "2"}, f"the plan's steps aren't planned as priority items: {steps}")
        led = (ws / "HQ/ledger/donna.md").read_text()
        need("· cycle plan (job " in led and "- pick: the plumber's bill · source: his order of today" in led and "- let go: the newsletters" in led
             and '"orders_done"' in led and "- escalated: If the plumber's bill" in led, f"the plan isn't in the ledger: {led[-900:]}")
        need(re.search(r'^- \S+ \S+ · start · "put the plumber\'s bill in Friday\'s block" · planned', led, re.M), f"the order isn't planned: {led[:700]}")
        thread = (ws / "HQ/direct-line/thread.jsonl").read_text() if (ws / "HQ/direct-line/thread.jsonl").exists() else ""
        need("If the plumber's bill is really due Friday" not in thread, "Donna's question went out at once instead of into her batch")
        state = json.loads(Path(env["HQ_CYCLES_STATE"]).read_text())
        need(any(x["text"].startswith("If the plumber's bill") for x in state["agents"]["donna"]["batch"]), f"the question isn't in her batch: {state['agents']['donna']}")
        kinds = json.loads((ws / "HQ/roadmap-estimates/schedule-kinds.json").read_text())
        need(all(kinds[x[0]]["kind"] == "step-donna" for x in steps), f"the steps' kinds: {[kinds[x[0]] for x in steps]}")
        # staleness: the first step's input (the to-do row) changes; promoted, its gatekeep says stale and cancels it
        r = sched("move", steps[0][0], "now"); need(r.returncode == 0, r.stdout + r.stderr)
        r = sched("promote"); need("became job" in r.stdout, r.stdout + r.stderr)
        (ws / "challenges.md").write_text((ws / "challenges.md").read_text().replace("| Pay the plumber | passive | 2026-12-01 | open |", "| Pay the plumber | passive | 2026-12-01 | scheduled |"))
        g = drive("gatekeep", time.strftime("%Y-%m-%d %H:%M"))
        need(g["verdict"] == "skipped" and any("stale" in x for x in g["log"]), f"a changed input isn't stale: {g}")
        led = (ws / "HQ/ledger/donna.md").read_text()
        need("step 1 stale" in led and "its input changed since the plan (todo plumber)" in led, f"stale isn't in the ledger: {led[-400:]}")
        need(not [j for j in json.loads(_sp.run([sys.executable, str(ROOT / "routine/jobs.py"), "next"], capture_output=True, text=True, env=env).stdout)["waiting"]], "the stale step still waits")
        # the second step, unchanged: go (inside the hours)
        r = sched("move", steps[1][0], "now"); need(r.returncode == 0, r.stdout + r.stderr)
        r = sched("promote"); need("became job" in r.stdout, r.stdout + r.stderr)
        g = drive("gatekeep", time.strftime("%Y-%m-%d %H:%M"))
        need(g["verdict"] == "go", f"an unchanged step doesn't get go: {g}")
        # failed twice: a tripwire text; a third tripwire that day: the ledger only
        cy("failed", "donna", "2", "the pile didn't shrink")
        cy("failed", "donna", "2", "still the same pile")
        thread = (ws / "HQ/direct-line/thread.jsonl").read_text()
        need(thread.count("failed twice") == 1, f"the failing-twice tripwire: {thread}")
        cy("failed", "donna", "2", "a third time")
        cy("failed", "donna", "2", "a fourth time")
        thread = (ws / "HQ/direct-line/thread.jsonl").read_text()
        need(thread.count("failed twice") == 2, f"more than her two texts a day went out: {thread}")
        led = (ws / "HQ/ledger/donna.md").read_text()
        need(led.count("- tripwire (a check failing twice)") == 3, f"the tripwires aren't all in the ledger: {led.count('tripwire')}")
        # the same goal planned again without done: held with a tripwire (the ledger; the texts are used up)
        r = cy("plan", "donna", json.dumps({"picks": ["x"], "steps": [{"goal": "clear the To check pile by the rules", "done_means": "smaller", "at": f"{hh[1]:02d}:30"}]}))
        need("1 step(s) held: the same goal was tried before" in r.stdout, f"the same goal twice isn't held: {r.stdout}")
        led = (ws / "HQ/ledger/donna.md").read_text()
        need("- tripwire (same goal twice)" in led, "the same-goal tripwire isn't in the ledger")
        r = cy("plan", "donna", bad, ok=False)
        need(r.returncode != 0 and "at most 3 picks" in r.stdout, f"four picks weren't refused: {r.stdout}")
        cy("set", "donna", "hours", "08:00-22:00")
        r = cy("plan", "donna", json.dumps({"picks": [], "steps": [{"goal": "x", "done_means": "y", "at": "23:30"}]}), ok=False)
        need(r.returncode != 0 and "outside your hours" in r.stdout, f"a step at night wasn't refused: {r.stdout}")
        # nothing restarts itself: no new step item for the stale or failed ones
        rm = (ws / "HQ/roadmap.md").read_text()
        need(len(re.findall(r"^- Item \d+ · waiting, priority · .* · Agent step: donna", rm, re.M)) == 0, f"a step was planned again by itself: {rm[-600:]}")
        return (f"Donna's session (job {s2['n']}) ran in its box with the handbook, her ledger and the order; its plan became two priority step items and the order "
                "planned; a step with a changed input is stale and cancelled, an unchanged one goes; failed twice is one text, the third tripwire the ledger only; "
                "the same goal twice is held; nothing restarts by itself")

    async def flow192(self) -> str:
        """H298, piece 6, no Claude: the wall, layer by layer, on a throwaway workspace with Donna's session waiting
        on the queue. (1) The gate: with the 5-hour line fixed and the saved usage over it, the routine's start check
        says STOP for the cycle job's need, as for any job (the same gate; tick.py asks it after the runner's own
        check). (2) The box is piece 3's (flow 187): ends a run at its minutes and at its turns. (3) The share: with
        her finished runs this week costing most of her share, her next run is refused and written as skipped; over
        her daily share the same. (4) The hours: at 23:00 nothing starts: the session is dropped (skipped, the ledger
        says the hours) and, when still useful tomorrow (Pepper's), planned again for the morning; at 07:00 it waits;
        past its useful-until it's skipped; boxed twice in a row is a tripwire on her line, and a boxed run is never
        planned again by the runner."""
        import subprocess as _sp
        ws, env = self._h298_ws("p6c")
        env["HQ_LEDGER_FOLDER"] = str(ws / "HQ/ledger")
        drv = self.tmp / "h298-driver.py"
        drv.write_text(self._h298_driver())
        def drive(*a, extra=None):
            r = _sp.run([sys.executable, str(drv), str(ROOT), str(ws), *a], capture_output=True, text=True, env={**env, **(extra or {})}, cwd=str(ROOT), timeout=300)
            m = re.search(r"RESULT (.*)", r.stdout)
            need(m, f"the driver failed: {r.stdout[-600:]} {r.stderr[-1500:]}")
            return json.loads(m.group(1))
        def cy(*a):
            r = _sp.run([sys.executable, str(ROOT / "routine/cycles.py"), *a], capture_output=True, text=True, env=env, cwd=str(ROOT))
            need(r.returncode == 0, f"cycles.py {' '.join(a)[:80]}: {r.stdout[-300:]} {r.stderr[-500:]}")
            return r.stdout
        def sched(*a):
            return _sp.run([sys.executable, str(ROOT / "routine/schedule.py"), *a], capture_output=True, text=True, env=env, cwd=str(ROOT))
        def jobs(*a):
            return _sp.run([sys.executable, str(ROOT / "routine/jobs.py"), *a], capture_output=True, text=True, env=env, cwd=str(ROOT))
        for a in ("pepper", "moneypenny"):
            cy("set", a, "on", "off")
        drive("tick")
        rm = ws / "HQ/roadmap.md"
        item = re.search(r"^- Item (\d+) · waiting, every day, priority · .* · Agent cycle: donna, bigger session$", rm.read_text(), re.M)
        need(item, "Donna's session isn't planned")
        need(sched("move", item.group(1), "now").returncode == 0 and "became job" in sched("promote").stdout, "the session didn't become a job")
        job = [j for j in json.loads(jobs("next").stdout)["waiting"]][0]
        # (1) the gate, as tick.py asks it right after the runner's check: the 5-hour line fixed at 20%, the usage at 60%
        rm.write_text(rm.read_text().replace("**Usage limit: 70%.**", "**Usage limit: 20%.**").replace("**5-hour line: moving.**", "**5-hour line: fixed.**"))
        status = Path(env["HQ_STATUS_DIR"])
        reset = (datetime.now(timezone.utc) + timedelta(hours=3)).strftime("%Y-%m-%dT%H:%M:%SZ")
        usage = {"readable": True, "checkedAt": datetime.now(timezone.utc).strftime("%Y-%m-%dT%H:%M:%SZ"),
                 "limits": [{"label": "5-hour", "percent": 60, "resetsAt": reset}, {"label": "Weekly (all models)", "percent": 10, "resetsAt": reset}]}
        hq_status = ROOT / ".status"
        hq_status.mkdir(exist_ok=True)
        keep = (hq_status / "usage.json").read_text() if (hq_status / "usage.json").exists() else None
        try:
            (hq_status / "usage.json").write_text(json.dumps(usage))
            g = _sp.run(["node", str(ROOT / "status/save-usage.mjs"), "--gate", "--minutes", "10", "--need", "five=1,weekly=1"], capture_output=True, text=True,
                        env={**env, "HQ_ROADMAP": str(rm)}, cwd=str(ROOT))
            need(g.returncode != 0 and g.stdout.startswith("STOP"), f"the gate doesn't hold a start over the line: {g.stdout} {g.stderr[-300:]}")
        finally:
            if keep is None:
                (hq_status / "usage.json").unlink(missing_ok=True)
            else:
                (hq_status / "usage.json").write_text(keep)
        tsrc = (ROOT / "routine/tick.py").read_text()
        need("cycles.gatekeep(cand" in tsrc and tsrc.index("cycles.gatekeep(cand") < tsrc.index('"--gate", "--reserve"]'), "tick.py doesn't ask the runner's check before the gate")
        # (4) the hours: 23:00 drops it (not useful tomorrow: Donna's until 12:00), 07:00 waits
        today = time.strftime("%Y-%m-%d")
        # The session counts as queued this morning, as on a run at night: a session queued after 12:00 is still useful
        # until tomorrow's 12:00, and would rightly be planned again for 08:00.
        rq = ws / "HQ/roadmap.md"
        morning = lambda m: re.sub(r"(, planned for \w+ \d{1,2} \w+, )\d{1,2}:\d\d:", r"\g<1>09:00:",  # noqa: E731
                                   re.sub(r"(· agreed \d{4}-\d\d-\d\d )\d\d:\d\d", r"\g<1>09:00", m.group(0), count=1), count=1)
        rq.write_text(re.sub(r"^- Job 1 · .*$", morning, rq.read_text(), count=1, flags=re.M))
        g = drive("gatekeep", f"{today} 23:00")
        need(g["verdict"] == "skipped" and any("hours end at 22:00" in x for x in g["log"]), f"at 23:00: {g}")
        led = (ws / "HQ/ledger/donna.md").read_text()
        need("bigger session skipped" in led and "the day's hours end at 22:00" in led and "planned again" not in led, f"the ledger after 23:00: {led[-400:]}")
        need(not json.loads(jobs("next").stdout)["waiting"], "the dropped job still waits")
        # Pepper's, useful until Friday 9:30: dropped at 22:30 and planned again for 08:00
        cy("set", "pepper", "on", "on")
        drive("tick")
        it = re.search(r"^- Item (\d+) · waiting, every thursday, priority · .* · Agent cycle: pepper, bigger session$", rm.read_text(), re.M)
        need(it and sched("move", it.group(1), "now").returncode == 0 and "became job" in sched("promote").stdout, "Pepper's session didn't become a job")
        # A Thursday still to come, 22:30, whatever day and hour the run is: the Friday morning after it must lie ahead
        # (schedule.py refuses a time gone by), with the job as planned for that Thursday, as on a real Thursday night.
        thu = datetime.now()
        thu = thu + timedelta(days=(3 - thu.weekday()) % 7 or 7)
        rq.write_text(re.sub(r"^- Job \d+ · .*Agent cycle: pepper, bigger session$",
                             lambda m: re.sub(r", planned for \w+ \d{1,2} \w+, \d{1,2}:\d\d:", thu.strftime(", planned for %A %d %B, 22:00:"), m.group(0), count=1),
                             rq.read_text(), flags=re.M))
        g = drive("gatekeep", thu.strftime("%Y-%m-%d") + " 22:30")
        need(g["verdict"] == "skipped", f"Pepper at 22:30: {g}")
        led = (ws / "HQ/ledger/pepper.md").read_text()
        need("planned again for Friday 08:00" in led, f"not planned again for the morning: {led[-300:]}")
        need(re.search(r"^- Item \d+ · waiting, priority · at \S+ 08:00 · .* · Agent cycle: pepper, bigger session$", rm.read_text(), re.M), "the morning item isn't on the schedule")
        # 07:00 waits
        it = re.search(r"^- Item (\d+) · waiting, priority · at \S+ 08:00 · .* · Agent cycle: pepper, bigger session$", rm.read_text(), re.M)
        need(sched("move", it.group(1), "now").returncode == 0 and "became job" in sched("promote").stdout, "the morning session didn't become a job")
        g = drive("gatekeep", f"{today} 07:00")
        need(g["verdict"] == "wait", f"at 07:00: {g}")
        # past its useful-until (Pepper's: Friday 09:30): skipped
        fri = thu + timedelta(days=1)
        g = drive("gatekeep", fri.strftime("%Y-%m-%d") + " 11:00")
        need(g["verdict"] == "skipped" and any("too late to be useful" in x for x in g["log"]), f"past useful-until: {g}")
        # (3) the share: her finished runs this week cost 2.8 of her 3 points; a run of about 1 point is refused
        drive("tick")
        it = re.search(r"^- Item (\d+) · waiting, every day, priority · .* · Agent cycle: donna, bigger session$", rm.read_text(), re.M)
        need(it and sched("move", it.group(1), "now").returncode == 0 and "became job" in sched("promote").stdout, "Donna's next session didn't become a job")
        est_dir = ws / "HQ/roadmap-estimates"
        est_dir.mkdir(exist_ok=True)
        now = time.time()
        with open(est_dir / "job-estimates-history.jsonl", "a") as f:
            for k, c in enumerate((1.0, 0.9, 0.9)):
                f.write(json.dumps({"n": 900 + k, "kind": "cycle-donna", "est": 8, "actual": 7, "done": int(now - 86400 * (k + 1)), "machine": "here",
                                    "cost": {"five": 2.0, "weekly": c}, "cost_how": "tokens", "tokens": {"opus": [1000, 200, 0, 0]}, "retag": 4}) + "\n")
        r = cy("set", "donna", "daily", "5")
        g = drive("gatekeep", f"{today} 10:00")
        need(g["verdict"] == "skipped" and any("over her weekly share" in x for x in g["log"]), f"over her share, but not refused: {g}")
        led = (ws / "HQ/ledger/donna.md").read_text()
        need("over her weekly share (2.8 of 3 points used" in led, f"the share isn't in the ledger: {led[-300:]}")
        # the daily share: today's runs cost 0.9 of a daily share of 1
        cy("set", "donna", "weekly", "20")
        with open(est_dir / "job-estimates-history.jsonl", "a") as f:
            f.write(json.dumps({"n": 910, "kind": "step-donna", "est": 3, "actual": 2, "done": int(now - 60), "machine": "here",
                                "cost": {"five": 1.0, "weekly": 0.9}, "cost_how": "tokens", "tokens": {"opus": [1000, 200, 0, 0]}, "retag": 4}) + "\n")
        cy("set", "donna", "daily", "1")
        drive("tick")
        it = re.search(r"^- Item (\d+) · waiting, every day, priority · .* · Agent cycle: donna, bigger session$", rm.read_text(), re.M)
        need(it and sched("move", it.group(1), "now").returncode == 0 and "became job" in sched("promote").stdout, "Donna's third session didn't become a job")
        g = drive("gatekeep", f"{today} 10:00")
        need(g["verdict"] == "skipped" and any("over her daily share" in x for x in g["log"]), f"over her daily share, but not refused: {g}")
        # a share of 0 refuses every start (it used to mean no share at all, so the wall let everything through)
        cy("set", "donna", "weekly", "0")
        cy("set", "donna", "daily", "5")
        drive("tick")
        it = re.search(r"^- Item (\d+) · waiting, every day, priority · .* · Agent cycle: donna, bigger session$", rm.read_text(), re.M)
        need(it and sched("move", it.group(1), "now").returncode == 0 and "became job" in sched("promote").stdout, "Donna's fourth session didn't become a job")
        g = drive("gatekeep", f"{today} 10:00")
        need(g["verdict"] == "skipped" and any("of 0 points used" in x for x in g["log"]), f"a weekly share of 0, but not refused: {g}")
        drive("tick")
        need("run: cancelled" not in (ws / "HQ/ledger/donna.md").read_text(), "a refused start is also written as a run")
        # boxed twice in a row: a tripwire on her line; a boxed run is never planned again by the runner
        code = ("import sys, json, datetime as dt; sys.path.insert(0, %r); import cycles, json\n"
                "from pathlib import Path\nrun = Path(%r)\n"
                "for n in (41, 42):\n"
                "    (run / f'job-{n}.box.json').write_text(json.dumps({'n': n, 'minutes': 10.1, 'turns': 31, 'steps': 12, 'boxed': 'turns', 'tools': [], 'refused': []}))\n"
                "    cycles.after_run({'n': n, 'text': 'Scheduled item 9, planned for Monday 1 January, 08:30: Agent cycle: donna, bigger session', 'state': 'done 08:41'}, "
                "{'agent': 'donna', 'kind': 'session', 'name': 'bigger session'}, run_dir=str(run))\n"
                "print('ok')") % (str(ROOT / "routine"), env["HQ_JOB_RUN"])
        self._h298_py(env, code)
        thread = (ws / "HQ/direct-line/thread.jsonl").read_text() if (ws / "HQ/direct-line/thread.jsonl").exists() else ""
        need(thread.count("ran out of their box") == 1, f"boxed twice isn't one text: {thread}")
        led = (ws / "HQ/ledger/donna.md").read_text()
        need(led.count("run: boxed at its turns") == 2 and "- tripwire (boxed twice in a row)" in led, f"the boxed runs aren't in the ledger: {led[-500:]}")
        before = rm.read_text()
        drive("tick")
        need(len(re.findall(r"Agent cycle: donna, bigger session", rm.read_text(), re.M)) == len(re.findall(r"Agent cycle: donna, bigger session", before, re.M)),
             "a boxed run was planned again by the runner")
        return "the gate STOPs over the line; 23:00 drops the session (Pepper's planned again for 08:00), 07:00 waits, past useful-until skips; over her weekly or daily share refuses, a share of 0 too, and a refused start isn't written as a run; boxed twice is one text and nothing restarts"

    async def flow193(self) -> str:
        """H298, piece 7, no Claude: the Friday screen on the status page. On a throwaway workspace with Donna's
        ledger carrying a plan, two scores and a tripwire, and her share partly used: routines.json carries the agents
        (on, three lines per agent, her share against her line), and the page draws The agents: one card per agent
        with picked, moved, escalated and the share, red when over her line; Pepper off isn't drawn. With the switch
        off, routines.json says off and the page has no such section (the senders section and the rest as before)."""
        import shutil as _sh
        import subprocess as _sp
        ws, env = self._h298_ws("p7")
        env["HQ_LEDGER_FOLDER"] = str(ws / "HQ/ledger")
        def py(code):
            return self._h298_py(env, "import sys; sys.path.insert(0, %r); sys.path.insert(0, %r)\n" % (str(ROOT / "routine"), str(ROOT / "app")) + code)
        def cy(*a):
            r = _sp.run([sys.executable, str(ROOT / "routine/cycles.py"), *a], capture_output=True, text=True, env=env, cwd=str(ROOT))
