# F63: every flow stops at six minutes, except those named here. Flow 44 reads every file and HQ's whole git
# history, which grows every day (217 s on 23 October, 360 s on 27 October), and checks all of it: it gets
# twenty minutes instead of checking less. Its time is in the summary, next to its limit, so a climb shows.
FLOW_LIMIT = 360
FLOW_LIMITS = {44: 1200, 472: 1800, 294: 420, 295: 14500, 300: 600, 301: 900, 302: 600, 303: 600, 371: 600, 373: 600}  # F115: 371 and 373 run two Syncthings each; 472: every extension's own flows, two minutes each at most


def limit_of(n: int) -> int:
    return FLOW_LIMITS.get(n, FLOW_LIMIT)


def rss_mb() -> int | None:
    """H162 (4 November 2026): this process's memory now, in MB (Linux only; None elsewhere). A full run had grown to 3.2 GB on the
    server, and with a job and a proof at the same time the kernel killed the night's jobs (494, 496, 498)."""
    try:
        for line in open("/proc/self/status"):
            if line.startswith("VmRSS:"):
                return int(line.split()[1]) // 1024
    except OSError:
        return None
    return None


MEMORY_STEP_MB = 100  # a flow that leaves the run this much bigger is named under it and in the summary


def let_go() -> None:
    """H162 (4 November 2026): after a flow that grew the run, give the memory back. The listener keeps each Whisper model it loaded for
    the life of the process (pipeline.HQFasterWhisperSTT._MODELS, right for the call line, where every call shares one), so in a run each
    flow that builds a call's pipeline added to it; and what a flow freed (Kokoro's voice, say) stayed with the process. The next flow
    that needs a model loads it again."""
    import gc
    pl = sys.modules.get("pipeline")
    stt = getattr(pl, "HQFasterWhisperSTT", None) if pl else None
    if stt is not None and getattr(stt, "_MODELS", None):
        with stt._LOCK:
            stt._MODELS.clear()
    gc.collect()
    if sys.platform.startswith("linux"):
        try:
            import ctypes
            ctypes.CDLL("libc.so.6").malloc_trim(0)
        except (OSError, AttributeError):
            pass


async def one_flow(res: Result, method, n: int) -> None:
    """One flow, and how it came out in res."""
    try:
        res.note = await asyncio.wait_for(method(), timeout=limit_of(n))
        res.status = "PASS"
    except Failed as e:
        res.status, res.note = "FAIL", str(e)
    except asyncio.TimeoutError as e:  # a wait inside the flow, or the flow's limit (six minutes, F63)
        res.status, res.note = "FAIL", str(e) or f"took longer than its limit of {limit_of(n) // 60} minutes"
    except Exception as e:  # a crash in a flow is a failed flow, not a failed run
        res.status, res.note = "FAIL", f"{type(e).__name__}: {e}"


async def canary() -> str | None:
    """F111: the canary. With need() emptied every flow used to pass and nothing said so. Before the first flow a flow with a false
    check goes the way every flow goes and has to fail; the small checks inside the flows' own scripts have to stop too. Why it
    didn't, or None."""
    async def bird():
        need(False, "a false check")
        return "it passed"
    res = Result(0, "The canary")
    await one_flow(res, bird, 0)
    if res.status != "FAIL" or res.note != "a false check":
        return f"the canary: a flow with a false check came out {res.status} ({res.note}), so a green run says nothing"
    text = Path(__file__).read_text(encoding="utf8")
    needs = re.findall(r"^def need\(ok, why\):\n((?: .*\n)+)", text, re.M)
    fails = re.findall(r"^fail\(\) \{(.*)\}$", text, re.M)
    if not all("sys.exit(1)" in b or "raise" in b for b in needs) or not all("exit 1" in b for b in fails):
        return "the canary: a check inside a flow's own script no longer stops it, so a green run says nothing"
    return None


async def main(args) -> bool:
    chosen = sorted(int(x) for x in args.only.split(",")) if args.only else sorted(FLOWS)
    chosen = [n for n in chosen if str(n) not in args.skip.split(",")]  # F101: the night's Mac-only ones
    bad = [n for n in chosen if n not in FLOWS]
    if bad:
        print(f"No such flow: {bad}. The flows are 1 to {len(FLOWS)}.")
        return False
    stamp = datetime.now().strftime("%Y-%m-%d %H:%M")
    print(f"== HQ happy flows · {stamp} · flows {chosen}" + (" · quick (no Claude turns)" if args.quick else ""))
    # F17: everything the flows start knows it's a test, and which roadmap and HQ memory are the real ones,
    # so jobs.py, schedule.py, set-status.py and role.py refuse them (a flow works on its own copies only).
    os.environ["HQ_UNDER_TEST"] = "1"
    os.environ["HQ_NO_WALL"] = "1"  # F100: the flows from before aren't about the wall; a wall flow takes this out again
    os.environ.setdefault("HQ_REAL_ROADMAP", os.path.realpath(ROADMAP))
    sys.path.insert(0, str(ROOT / "routine"))
    import hqpaths as _hqp
    os.environ.setdefault("HQ_REAL_SUPPORT", _hqp.real_support())
    import testwall
    watch = testwall.Watch()
    tmp = Path(tempfile.mkdtemp(prefix="happy-flows-", dir=config.SCRATCH))
    run_ = Run(tmp)
    # Flow 7 closes the live call; if it runs, it must come after the others that use that call.
    results: list[Result] = []
    t_all = time.perf_counter()
    mem_start = rss_mb()
    grew: list[tuple[int, int]] = []  # (flow, MB it added)
    dead = await canary()
    if dead:
        results.append(Result(0, "The canary", "FAIL", 0.0, dead))
        chosen = []
    try:
        for n in chosen:
            name, uses_claude, method = FLOWS[n]
            res = Result(n, name)
            results.append(res)
            if args.quick and uses_claude:
                res.note = "skipped (--quick)"
                continue
            if testwall.outer_gone():  # F111: whoever started this run is gone, and its folder goes with it
                print("The run that started this one is gone: stopping.", flush=True)
                break
            print(f"\n-- {n} · {name}", flush=True)
            testwall.mark(n, uses_claude)
            t = time.perf_counter()
            before = rss_mb()
            await one_flow(res, getattr(run_, method), n)
            res.secs = time.perf_counter() - t
            watch.after(n)
            say(f"{res.status}: {res.note}")
            after = rss_mb()
            if before is not None and after is not None and after - before >= MEMORY_STEP_MB:
                grew.append((n, after - before))
                let_go()
                say(f"memory: {after} MB, {after - before} MB more after this flow; {rss_mb()} MB once let go")
    finally:
        try:
            if run_.live:
                await run_.live.close()
        except Exception as e:
            print(f"(closing the live test call: {e!r})")
        if listening_pids(TEST_PORT):
            await asyncio.to_thread(run_.server.stop)
        live_after = (listening_pids(config.PORT) or [None])[0]
        turns = run_.turns + (run_.live.turns_used if run_.live else 0)
        if not args.keep:
            shutil.rmtree(tmp, ignore_errors=True)

    print("\n== Result")
    for r in results:
        own = f" (limit {limit_of(r.num) // 60} min)" if r.num in FLOW_LIMITS else ""
        print(f" {r.num:>2}  {r.name:<58} {r.status:<5} {r.secs:5.0f} s{own}" if r.status != "SKIP"
              else f" {r.num:>2}  {r.name:<58} SKIP")
    ran = [r for r in results if r.status != "SKIP"]
    failed = [r for r in ran if r.status == "FAIL"]
    for r in results:
        print(f"      {r.num:>2}: {r.note}" if r.status != "FAIL" else f"      {r.num:>2}: FAILED - {r.note}")
    guard = "live server on 7860 untouched" if live_after == run_.live_pid_before else \
        f"WARNING: the live server's pid changed ({run_.live_pid_before} -> {live_after})"
    real_runs, stopped = testwall.model_calls()  # F111: the true counts, from every call that went through the stand-in
    mem_end = rss_mb()
    if mem_start is not None and mem_end is not None:
        most = ", ".join(f"{n} (+{mb} MB)" for n, mb in sorted(grew, key=lambda g: -g[1])[:8])
        print(f"\n== Memory\n{mem_start} MB at the start, {mem_end} MB at the end" + (f"; grew most in flow {most}" if most else ""))
    print(f"\n{len(ran) - len(failed)} of {len(ran)} passed · {turns} Claude turns · {real_runs} real model runs, {stopped} stopped at the stand-in"
          f" · {time.perf_counter() - t_all:.0f} s · {guard}")
    testwall.finished()
    return not failed and live_after == run_.live_pid_before


if __name__ == "__main__":
    p = argparse.ArgumentParser(description="HQ happy flows (phase G)")
    p.add_argument("--only", default="", help="comma-separated flow numbers, e.g. 3,5")
    p.add_argument("--skip", default="", help="comma-separated flow numbers to leave out")
    p.add_argument("--quick", action="store_true", help="skip the flows that use Claude turns (2-7)")
    p.add_argument("--keep", action="store_true", help="keep the scratch folder")
    p.add_argument("-v", "--verbose", action="store_true")
    a = p.parse_args()
    sys.path.insert(0, str(ROOT / "routine"))
    import testwall as _wall  # F111: the flows run behind the wall, whoever starts them; here is the side outside it
    if not _wall.inside(ROOT):
        sys.exit(_wall.run(sys.argv[1:], ROOT, keep=a.keep))
    if a.verbose:
        from loguru import logger
        logger.remove()
        logger.add(sys.stderr, level="DEBUG")
    else:
        from loguru import logger
        logger.remove()
        logger.add(sys.stderr, level="WARNING")
    signal.signal(signal.SIGTERM, lambda *_: sys.exit(1))
    sys.exit(0 if asyncio.run(main(a)) else 1)
